// ═══════════════════════════════════════════
// render.js — Cumulative & project view rendering
// ═══════════════════════════════════════════

// ═══════ RENDER ═══════
function renderMain(){Object.values(charts).forEach(c=>{try{c.destroy()}catch(e){}});charts={};const mc=document.getElementById('mainContent');curView()==='cumulative'?renderCumulative(mc):renderProject(mc)}

// ═══════ CUMULATIVE ═══════
function renderCumulative(mc){const d=curDash(),all=allTCs(),n=all.length;
if(!d.projectIds.length){mc.innerHTML='<div class="empty-state"><h2>No Projects</h2><p>Create a project to start.</p><div class="actions"><button class="btn btn-primary" onclick="createProject()">+ Project</button></div></div>';return}
const pa=all.filter(t=>t.status==='Pass').length,fa=all.filter(t=>t.status==='Fail').length,bl=all.filter(t=>t.status==='Blocked').length,pi=all.filter(t=>t.status==='Pending Input').length,ex=all.filter(isExec).length,pr=ex>0?Math.round(pa/ex*100):0;
const oi=all.reduce((s,t)=>s+(t.subItems||[]).filter(si=>!['Closed','Done'].includes(si.status)).length,0);
const allDefects=d.projectIds.flatMap(pid=>(projects[pid]?.defects||[]).map(df=>({...df,_pt:projects[pid]?.title||pid,_pid:pid})));
const openDef=allDefects.filter(df=>!['Verified','Closed'].includes(df.status)).length;
const blockedTCs=all.filter(t=>t.status==='Blocked');
let h=`<div class="kpi-grid">
<div class="kpi-card"><div class="kpi-label">Total TCs</div><div class="kpi-value" style="color:var(--accent)">${n}</div><div class="kpi-sub">${d.projectIds.length} projects</div></div>
<div class="kpi-card"><div class="kpi-label">Passed</div><div class="kpi-value" style="color:var(--success)">${pa}</div><div class="kpi-sub">${pr}% rate</div></div>
<div class="kpi-card"><div class="kpi-label">Failed</div><div class="kpi-value" style="color:var(--fail)">${fa}</div></div>
<div class="kpi-card"><div class="kpi-label">Blocked</div><div class="kpi-value" style="color:var(--blocked)">${bl}</div></div>
<div class="kpi-card"><div class="kpi-label">Executed</div><div class="kpi-value" style="color:var(--warning)">${ex}</div><div class="kpi-sub">${n?Math.round(ex/n*100):0}%</div></div>
<div class="kpi-card"><div class="kpi-label">Open Items</div><div class="kpi-value" style="color:var(--deferred)">${oi}</div></div>
<div class="kpi-card"><div class="kpi-label">Open Defects</div><div class="kpi-value" style="color:var(--fail)">${openDef}</div><div class="kpi-sub">${allDefects.length} total</div></div>
<div class="kpi-card"><div class="kpi-label">Script Done</div><div class="kpi-value" style="color:var(--info)">${all.filter(t=>t.scriptStatus==='Done').length}</div></div>
</div>`;
// Charts - 4 panels
h+=`<div class="chart-grid"><div class="chart-card"><h3>Status Distribution</h3><div class="chart-container"><canvas id="cS"></canvas></div></div><div class="chart-card"><h3>Priority Distribution</h3><div class="chart-container"><canvas id="cPri"></canvas></div></div><div class="chart-card"><h3>Execution Progress</h3><div class="chart-container"><canvas id="cP"></canvas></div></div><div class="chart-card"><h3>Blocking Reasons</h3><div class="chart-container"><canvas id="cBR"></canvas></div></div></div>`;
// UNIFIED Updates
h+=`<div class="section-header"><h2>Updates & Accomplishments</h2></div><div class="log-form no-pdf"><select id="dLT"><option>Update</option><option>Accomplishment</option></select><input id="dLX" placeholder="Add an update..." style="width:100%" onkeydown="if(event.key==='Enter')addUnifiedLog()"><button class="btn btn-sm btn-primary" onclick="addUnifiedLog()">Add</button></div>`;
h+=`<div class="filters-bar no-pdf"><select class="filter-select" id="cumLogSrc" onchange="renderUnifiedLogs()"><option value="">All Sources</option><option value="_dash">Dashboard Level</option>${d.projectIds.map(pid=>`<option value="${pid}">${esc(projects[pid]?.title)}</option>`).join('')}</select><select class="filter-select" id="cumLogTF" onchange="renderUnifiedLogs()"><option value="">All Types</option><option>Update</option><option>Accomplishment</option></select></div><div id="uLL"></div>`;
// UNIFIED Risks
h+=`<div class="section-header"><h2>Risk Register</h2></div><div style="display:grid;grid-template-columns:1fr auto auto auto auto;gap:8px;align-items:end;margin-bottom:12px" class="no-pdf"><input id="dRT" placeholder="Risk description..." style="font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><select id="dRC" style="font-size:12px;padding:7px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${RISK_CATS.map(c=>`<option>${c}</option>`).join('')}<option>Other</option></select><select id="dRS" style="font-size:12px;padding:7px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><option>Critical</option><option>High</option><option selected>Medium</option><option>Low</option></select><input id="dRO" placeholder="Owner" style="width:100px;font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><button class="btn btn-sm btn-primary" onclick="addUnifiedRisk()">Add</button></div>`;
h+=`<div class="filters-bar no-pdf"><select class="filter-select" id="cumRSrc" onchange="renderUnifiedRisks()"><option value="">All Sources</option><option value="_dash">Dashboard Level</option>${d.projectIds.map(pid=>`<option value="${pid}">${esc(projects[pid]?.title)}</option>`).join('')}</select><select class="filter-select" id="cumRCF" onchange="renderUnifiedRisks()"><option value="">All Categories</option>${RISK_CATS.map(c=>`<option>${c}</option>`).join('')}<option>Other</option></select><select class="filter-select" id="cumRSF" onchange="renderUnifiedRisks()"><option value="">All Statuses</option>${RISK_STATUSES.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="uRL"></div>`;
// Blockers list
h+=`<div class="section-header"><h2>Blockers <span class="count">${blockedTCs.length}</span></h2></div><div id="cumBlockList"></div>`;
// Per-project breakdown
h+=`<div class="section-header"><h2>Per-Project Breakdown</h2></div>`;
d.projectIds.forEach(pid=>{const proj=projects[pid];if(!proj)return;const tc=proj.testCases||[],pn=tc.length,pp=tc.filter(t=>t.status==='Pass').length,pf=tc.filter(t=>t.status==='Fail').length,pb=tc.filter(t=>t.status==='Blocked').length,pe=tc.filter(isExec).length;
h+=`<div class="proj-card"><h3 onclick="switchView('${pid}');document.getElementById('viewSelect').value='${pid}'">${esc(proj.title)} →</h3>${proj.goal?`<div style="font-size:12px;color:var(--text-secondary);margin-bottom:10px">${esc(proj.goal)}</div>`:''}<div class="proj-mini-kpis"><div class="proj-mini-kpi"><div class="val" style="color:var(--accent)">${pn}</div>Total</div><div class="proj-mini-kpi"><div class="val" style="color:var(--success)">${pp}</div>Pass</div><div class="proj-mini-kpi"><div class="val" style="color:var(--fail)">${pf}</div>Fail</div><div class="proj-mini-kpi"><div class="val" style="color:var(--blocked)">${pb}</div>Blocked</div><div class="proj-mini-kpi"><div class="val" style="color:var(--warning)">${pe}</div>Exec</div><div class="proj-mini-kpi"><div class="val" style="color:var(--fail)">${(proj.defects||[]).filter(d=>!['Verified','Closed'].includes(d.status)).length}</div>Defects</div></div></div>`});
// Requirements & Defects
const allReqs=[];d.projectIds.forEach(pid=>{const proj=projects[pid];if(!proj)return;(proj.requirements||[]).forEach(r=>allReqs.push({...r,_pid:pid,_pt:proj.title}))});
h+=`<div class="section-header"><h2>Requirements <span class="count">${allReqs.length}</span></h2></div><div id="cumReqList"></div>`;
h+=`<div class="section-header"><h2>Defect Log <span class="count">${allDefects.length}</span></h2></div><div id="cumDefList"></div>`;
h+=`<div style="margin-top:24px;padding-top:16px;border-top:1px solid var(--border);display:flex;gap:10px;flex-wrap:wrap" class="no-pdf"><button class="btn" onclick="exportDashCSV()">📊 Export CSV</button><button class="btn" onclick="exportDashJSON()">💾 Backup</button></div>`;
mc.innerHTML=h;
// Render charts
const cf={family:"'DM Sans',sans-serif",size:11},grd='rgba(255,255,255,.06)';
const sC={};STATUSES.forEach(s=>sC[s]=0);all.forEach(t=>{if(sC[t.status]!==undefined)sC[t.status]++});
charts.cS=createStatusDoughnut('cS',all);
charts.cPri=createPriorityBar('cPri',all);
charts.cP=createProgressDoughnut('cP',ex,n);
charts.cBR=createBlockingDoughnut('cBR',blockedTCs);
renderUnifiedLogs();renderUnifiedRisks();renderCumBlockers();renderCumReqs();renderCumDefs()}

// UNIFIED LOGS (dashboard + all projects merged)
function addUnifiedLog(){const d=curDash(),t=document.getElementById('dLT').value,x=document.getElementById('dLX').value.trim();if(!x)return;if(!d.logEntries)d.logEntries=[];d.logEntries.unshift({type:t,text:x,date:new Date().toISOString()});document.getElementById('dLX').value='';saveDash(meta.currentDashId);renderUnifiedLogs()}
function renderUnifiedLogs(){const el=document.getElementById('uLL');if(!el)return;const d=curDash(),srcF=document.getElementById('cumLogSrc')?.value||'',typeF=document.getElementById('cumLogTF')?.value||'';
let items=[];(d.logEntries||[]).forEach(e=>items.push({...e,_src:'Dashboard',_srcId:'_dash'}));d.projectIds.forEach(pid=>{const p=projects[pid];if(!p)return;(p.logEntries||[]).forEach(e=>items.push({...e,_src:p.title,_srcId:pid}))});
items.sort((a,b)=>new Date(b.date)-new Date(a.date));
if(srcF)items=items.filter(i=>i._srcId===srcF);if(typeF)items=items.filter(i=>i.type===typeF);
if(!items.length){el.innerHTML='<div style="text-align:center;padding:16px;color:var(--text-muted)">No entries.</div>';return}
el.innerHTML=items.slice(0,40).map(e=>`<div class="log-entry"><div class="log-header"><div style="display:flex;gap:8px;align-items:center"><span class="log-type ${e.type==='Update'?'log-type-update':'log-type-accomplishment'}">${esc(e.type)}</span><span style="font-size:11px;color:var(--accent);font-family:var(--font-mono);background:var(--bg-input);padding:1px 6px;border-radius:3px;border:1px solid var(--border)">${esc(e._src)}</span></div><span class="log-date">${new Date(e.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div><div class="log-text">${esc(e.text)}</div></div>`).join('')}

// UNIFIED RISKS (dashboard + all projects merged)
function addUnifiedRisk(){const d=curDash(),t=document.getElementById('dRT').value.trim(),c=document.getElementById('dRC').value,sv=document.getElementById('dRS').value,ow=document.getElementById('dRO').value.trim();if(!t)return;if(!d.risks)d.risks=[];d.risks.push({text:t,category:c,severity:sv,owner:ow,status:'New',date:new Date().toISOString()});document.getElementById('dRT').value='';document.getElementById('dRO').value='';saveDash(meta.currentDashId);renderUnifiedRisks()}
function renderUnifiedRisks(){const el=document.getElementById('uRL');if(!el)return;const d=curDash(),srcF=document.getElementById('cumRSrc')?.value||'',catF=document.getElementById('cumRCF')?.value||'',stF=document.getElementById('cumRSF')?.value||'';
let items=[];(d.risks||[]).forEach(r=>items.push({...r,_src:'Dashboard',_srcId:'_dash'}));d.projectIds.forEach(pid=>{const p=projects[pid];if(!p)return;(p.risks||[]).forEach(r=>items.push({...r,_src:p.title,_srcId:pid}))});
if(srcF)items=items.filter(i=>i._srcId===srcF);if(catF)items=items.filter(i=>i.category===catF);if(stF)items=items.filter(i=>i.status===stF);
if(!items.length){el.innerHTML='<div style="text-align:center;padding:16px;color:var(--text-muted)">No risks.</div>';return}
el.innerHTML=items.map(r=>`<div class="risk-card"><span class="priority-badge priority-${r.severity.toLowerCase()}">${esc(r.severity)}</span><span class="risk-cat-badge">${esc(r.category||'-')}</span><span class="risk-status-badge ${RSC[r.status]||'risk-new'}">${esc(r.status)}</span><span style="flex:1">${esc(r.text)}</span><span style="font-size:11px;color:var(--accent);font-family:var(--font-mono);background:var(--bg-input);padding:1px 6px;border-radius:3px;border:1px solid var(--border)">${esc(r._src)}</span><span style="font-size:12px;color:var(--text-secondary)">${esc(r.owner)||'-'}</span></div>`).join('')}

// BLOCKERS LIST
function renderCumBlockers(){const el=document.getElementById('cumBlockList');if(!el)return;const d=curDash();const blocked=[];d.projectIds.forEach(pid=>{const p=projects[pid];if(!p)return;p.testCases.filter(t=>t.status==='Blocked').forEach(tc=>{const ti=p.testCases.indexOf(tc);blocked.push({...tc,_pid:pid,_pt:p.title,_ti:ti})})});
if(!blocked.length){el.innerHTML='<div style="text-align:center;padding:20px;color:var(--text-muted)">No blocked test cases.</div>';return}
el.innerHTML=blocked.map(t=>`<div class="risk-card"><span class="td-id" onclick="openTcCross('${t._pid}',${t._ti})" style="cursor:pointer">${esc(t.tc_id)}</span><span class="priority-badge priority-${(t.priority||'Medium').toLowerCase()}">${esc(t.priority||'Medium')}</span><span style="font-size:12px;color:var(--blocked);font-family:var(--font-mono);font-weight:600">${esc(t.blockingReason||'No reason')}</span><span style="flex:1;font-size:13px;color:var(--text-secondary)">${esc(t.scenarioName)}</span><span style="font-size:11px;color:var(--accent);font-family:var(--font-mono);background:var(--bg-input);padding:1px 6px;border-radius:3px;border:1px solid var(--border)">${esc(t._pt)}</span></div>`).join('')}

// (unified logs/risks handled above)
// Cumulative requirements
function renderCumReqs(){const el=document.getElementById('cumReqList');if(!el)return;const d=curDash();let allR=[];d.projectIds.forEach(pid=>{const p=projects[pid];if(!p)return;(p.requirements||[]).forEach(r=>allR.push({...r,_pid:pid,_pt:p.title}))});if(!allR.length){el.innerHTML='<div style="text-align:center;padding:20px;color:var(--text-muted)">No requirements.</div>';return}el.innerHTML=allR.map(r=>{const p=projects[r._pid],cov=getReqCovP(r,p),cc=cov==='Covered'?'coverage-covered':cov==='Missing'?'coverage-missing':'coverage-at-risk';const chips=r.linkedTCs.length?r.linkedTCs.map(tid=>{const f=p.testCases.find(t=>t.tc_id===tid),ti=f?p.testCases.indexOf(f):-1,si=f?'status-'+f.status.toLowerCase().replace(/\s+/g,'-'):'';return`<span class="req-link-chip"><span class="status-badge ${si}" style="padding:1px 6px;font-size:10px;cursor:pointer" onclick="openTcCross('${r._pid}',${ti})">${esc(tid)}</span></span>`}).join(''):'<span style="font-size:12px;color:var(--text-muted);font-style:italic">None</span>';return`<div class="req-card"><div class="req-header"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span class="req-id">${esc(r.id)}</span><span class="coverage-badge ${cc}">${cov}</span>${r.reference?`<span style="font-size:11px;color:var(--text-muted);font-family:var(--font-mono)">ref: ${esc(r.reference)}</span>`:''}<span style="font-size:11px;color:var(--accent);font-family:var(--font-mono);background:var(--bg-input);padding:1px 8px;border-radius:4px;border:1px solid var(--border)">${esc(r._pt)}</span></div></div><div style="font-size:13px;color:var(--text-secondary);margin:6px 0">${esc(r.description)}</div><div class="req-links">${chips}</div></div>`}).join('')}
// Cumulative defects
function renderCumDefs(){const el=document.getElementById('cumDefList');if(!el)return;const d=curDash();let allD=[];d.projectIds.forEach(pid=>{const p=projects[pid];if(!p)return;(p.defects||[]).forEach((df,di)=>allD.push({...df,_pt:p.title,_pid:pid,_di:di}))});if(!allD.length){el.innerHTML='<div style="text-align:center;padding:20px;color:var(--text-muted)">No defects.</div>';return}el.innerHTML=allD.map(df=>{const p=projects[df._pid];const ti=df.linkedTC&&p?p.testCases.findIndex(t=>t.tc_id===df.linkedTC):-1;const refDisplay=df.externalRef?shortLink(df.externalRef):'';return`<div class="defect-card"><span class="defect-id" style="cursor:pointer;text-decoration:underline;text-decoration-style:dotted;text-underline-offset:3px" onclick="openDefectViewCross('${df._pid}',${df._di})">${esc(df.id)}</span><span class="priority-badge priority-${df.severity.toLowerCase()}">${esc(df.severity)}</span><span class="defect-status ${DSC[df.status]||'ds-new'}">${esc(df.status)}</span><span style="flex:1">${esc(df.title)}</span>${df.linkedTC?`<span class="td-id" style="cursor:pointer" onclick="${ti>=0?`openTcCross('${df._pid}',${ti})`:''}">${esc(df.linkedTC)}</span>`:''}${refDisplay?`<a href="${esc(df.externalRef)}" target="_blank" rel="noopener" style="font-family:var(--font-mono);font-size:11px;color:var(--accent);text-decoration:underline;text-underline-offset:2px">${esc(refDisplay.toUpperCase())}</a>`:''}<span style="font-size:11px;color:var(--accent);font-family:var(--font-mono);background:var(--bg-input);padding:1px 6px;border-radius:3px;border:1px solid var(--border)">${esc(df._pt)}</span></div>`}).join('')}
function getReqCovP(r,p){if(!r.linkedTCs.length)return'Missing';const l=r.linkedTCs.map(id=>p.testCases.find(t=>t.tc_id===id)).filter(Boolean);if(l.some(t=>t.status==='Blocked'||t.status==='Pending Input'||(t.subItems||[]).some(si=>si.type==='Clarification'&&!['Closed','Done'].includes(si.status))))return'At Risk';return'Covered'}
function openTcCross(pid,ti){const prev=curView();curDash().currentView=pid;openTcModal2(ti);const cb=document.querySelector('#tcModalContent .btn-ghost');if(cb)cb.setAttribute('onclick',`closeModal('tcModal');curDash().currentView='cumulative';saveDash(meta.currentDashId);renderMain()`)}
function exportDashCSV(){const d=curDash();let csv='';d.projectIds.forEach(pid=>{const p=projects[pid];if(!p)return;csv+=`\n=== ${p.title} ===\nTC_ID,Area,Scenario,Expected,Type,Priority,Status,Script\n`;p.testCases.forEach(tc=>{csv+=`${tc.tc_id},${tc.validationArea},${tc.scenarioName},${tc.expectedResults},${tc.typeOfTest},${tc.priority||'Medium'},${tc.status},${tc.scriptStatus||'Todo'}\n`})});downloadFile(`${d.title}_all.csv`,csv,'text/csv');showToast('Exported','success')}

// ═══════ PROJECT VIEW ═══════
function renderProject(mc){const pid=curView(),p=projects[pid];if(!p){mc.innerHTML='<div class="empty-state"><h2>Not found</h2></div>';return}const tc=p.testCases||[],n=tc.length,pa=tc.filter(t=>t.status==='Pass').length,fa=tc.filter(t=>t.status==='Fail').length,bl=tc.filter(t=>t.status==='Blocked').length,pi=tc.filter(t=>t.status==='Pending Input').length,ex=tc.filter(isExec).length,pr=ex>0?Math.round(pa/ex*100):0,oi=tc.reduce((s,t)=>s+(t.subItems||[]).filter(si=>!['Closed','Done'].includes(si.status)).length,0),scr=tc.filter(t=>t.scriptStatus==='Done').length,openDef=(p.defects||[]).filter(d=>!['Verified','Closed'].includes(d.status)).length;
let h=`<h2 style="font-family:var(--font-mono);font-size:18px;margin-bottom:8px"><input type="text" value="${esc(p.title)}" onchange="projects['${pid}'].title=this.value;saveProj('${pid}');renderNav()" style="font-family:var(--font-mono);font-size:18px;font-weight:600;background:transparent;border:1px solid transparent;color:var(--text-primary);padding:4px 8px;border-radius:var(--radius);width:600px;max-width:70vw" onfocus="this.style.borderColor='var(--border-focus)';this.style.background='var(--bg-input)'" onblur="this.style.borderColor='transparent';this.style.background='transparent'"></h2>`;
h+=`<div style="margin-bottom:20px;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:14px 18px"><label style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:6px;font-family:var(--font-mono)">Project Goal</label><textarea placeholder="Describe the testing effort..." onchange="projects['${pid}'].goal=this.value;saveProj('${pid}')" style="width:100%;font-family:var(--font-sans);font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary);resize:vertical;min-height:48px">${esc(p.goal||'')}</textarea></div>`;
h+=`<div class="kpi-grid"><div class="kpi-card"><div class="kpi-label">Total</div><div class="kpi-value" style="color:var(--accent)">${n}</div></div><div class="kpi-card"><div class="kpi-label">Passed</div><div class="kpi-value" style="color:var(--success)">${pa}</div><div class="kpi-sub">${pr}%</div></div><div class="kpi-card"><div class="kpi-label">Failed</div><div class="kpi-value" style="color:var(--fail)">${fa}</div></div><div class="kpi-card"><div class="kpi-label">Blocked</div><div class="kpi-value" style="color:var(--blocked)">${bl}</div></div><div class="kpi-card"><div class="kpi-label">Executed</div><div class="kpi-value" style="color:var(--warning)">${ex}</div><div class="kpi-sub">${n?Math.round(ex/n*100):0}%</div></div><div class="kpi-card"><div class="kpi-label">Open Items</div><div class="kpi-value" style="color:var(--deferred)">${oi}</div></div><div class="kpi-card"><div class="kpi-label">Defects</div><div class="kpi-value" style="color:var(--fail)">${openDef}</div><div class="kpi-sub">${(p.defects||[]).length} total</div></div><div class="kpi-card"><div class="kpi-label">Scripted</div><div class="kpi-value" style="color:var(--info)">${scr}</div></div></div>`;
h+=`<div class="chart-grid"><div class="chart-card"><h3>Status Distribution</h3><div class="chart-container"><canvas id="pS"></canvas></div></div><div class="chart-card"><h3>Priority Distribution</h3><div class="chart-container"><canvas id="pPri"></canvas></div></div><div class="chart-card"><h3>Execution Progress</h3><div class="chart-container"><canvas id="pP"></canvas></div></div><div class="chart-card"><h3>Blocking Reasons</h3><div class="chart-container"><canvas id="pBR"></canvas></div></div></div>`;
h+=`<div class="section-header"><h2>Updates</h2></div><div class="log-form no-pdf"><select id="pLT"><option>Update</option><option>Accomplishment</option></select><input id="pLX" placeholder="Update..." style="width:100%" onkeydown="if(event.key==='Enter')addPLog()"><button class="btn btn-sm btn-primary" onclick="addPLog()">Add</button></div><div id="pLL"></div>`;
h+=`<div class="section-header"><h2>Risks <span class="count">${(p.risks||[]).length}</span></h2></div><div style="display:grid;grid-template-columns:1fr auto auto auto auto;gap:8px;align-items:end;margin-bottom:12px" class="no-pdf"><input id="pRT" placeholder="Risk..." style="font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><select id="pRC" style="font-size:12px;padding:7px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${RISK_CATS.map(c=>`<option>${c}</option>`).join('')}<option>Other</option></select><select id="pRS" style="font-size:12px;padding:7px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><option>Critical</option><option>High</option><option selected>Medium</option><option>Low</option></select><input id="pRO" placeholder="Owner" style="width:100px;font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><button class="btn btn-sm btn-primary" onclick="addPRisk()">Add</button></div><div id="pRL"></div>`;
// TABS
h+=`<div class="tab-bar"><button class="tab-btn active" onclick="stab('tc',this)">Test Cases</button><button class="tab-btn" onclick="stab('ai',this)">Action Items</button><button class="tab-btn" onclick="stab('def',this)">Defects</button><button class="tab-btn" onclick="stab('req',this)">Requirements</button></div>`;
// TC tab
h+=`<div id="tab-tc" class="tab-content active"><div class="section-header"><h2>Test Cases <span class="count" id="tcC">${n}</span></h2><div style="display:flex;gap:8px"><button class="btn btn-sm btn-primary" onclick="openAddTcModal()">+ Add TC</button><button class="btn btn-sm" onclick="eAll()">Expand</button><button class="btn btn-sm" onclick="cAll()">Collapse</button></div></div><div class="filters-bar no-pdf"><input class="filter-input" id="sf" placeholder="Search..." oninput="rTT()"><select class="filter-select" id="stf" onchange="rTT()"><option value="">All Statuses</option>${STATUSES.map(s=>`<option>${s}</option>`).join('')}</select><select class="filter-select" id="prf" onchange="rTT()"><option value="">All Priorities</option>${PRIORITIES.map(p=>`<option>${p}</option>`).join('')}</select><button class="btn btn-sm btn-ghost" onclick="document.getElementById('sf').value='';document.getElementById('stf').value='';document.getElementById('prf').value='';rTT()">Clear</button></div><div class="table-wrap"><div class="table-scroll"><table><thead><tr><th style="width:28px"></th><th>ID</th><th>Area</th><th>Scenario</th><th>Expected</th><th>Type</th><th>Priority</th><th>Status</th><th>Script</th><th>Items</th></tr></thead><tbody id="tcB"></tbody></table></div></div></div>`;
// AI tab
h+=`<div id="tab-ai" class="tab-content"><div class="section-header"><h2>Action Items <span class="count" id="aiC">0</span></h2></div><div class="filters-bar no-pdf"><select class="filter-select" id="aitf" onchange="rAI()"><option value="">All Types</option><option>Clarification</option><option>Action Item</option><option>Dependency</option></select><select class="filter-select" id="aisf" onchange="rAI()"><option value="">All Statuses</option>${SUB_STATUSES.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="aiL"></div></div>`;
// Defect tab
h+=`<div id="tab-def" class="tab-content"><div class="section-header"><h2>Defect Log <span class="count" id="dfC">${(p.defects||[]).length}</span></h2><button class="btn btn-sm btn-primary no-pdf" onclick="openDefectModal('')">+ Log Defect</button></div><div id="dfL"></div></div>`;
// Req tab
h+=`<div id="tab-req" class="tab-content"><div class="section-header"><h2>Requirements <span class="count" id="rqC">0</span></h2></div><div style="display:grid;grid-template-columns:100px 120px 1fr auto;gap:10px;align-items:end;margin-bottom:12px" class="no-pdf"><input id="rqI" placeholder="REQ-001" style="font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><input id="rqR" placeholder="Reference" style="font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><input id="rqD" placeholder="Description..." onkeydown="if(event.key==='Enter')addReq()" style="font-size:13px;padding:7px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><button class="btn btn-sm btn-primary" onclick="addReq()">Add</button></div><div id="rqL"></div></div>`;
h+=`<div style="margin-top:24px;padding-top:16px;border-top:1px solid var(--border);display:flex;gap:10px;flex-wrap:wrap" class="no-pdf"><button class="btn" onclick="exportProjCSV()">📊 CSV</button><button class="btn btn-danger" onclick="resetProj()" style="margin-left:auto">🗑 Reset</button></div>`;
mc.innerHTML=h;
charts.pS=createStatusDoughnut('pS',tc);
charts.pPri=createPriorityBar('pPri',tc);
charts.pP=createProgressDoughnut('pP',ex,n);
charts.pBR=createBlockingDoughnut('pBR',tc.filter(t=>t.status==='Blocked'));
renderPLogs();renderPRisks();rTT();rAI();renderDefs();renderReqs()}

// Project logs & risks
function addPLog(){const p=curProj(),t=document.getElementById('pLT').value,x=document.getElementById('pLX').value.trim();if(!x||!p)return;if(!p.logEntries)p.logEntries=[];p.logEntries.unshift({type:t,text:x,date:new Date().toISOString()});document.getElementById('pLX').value='';saveProj(curView());renderPLogs()}
function renderPLogs(){const el=document.getElementById('pLL');if(!el)return;const p=curProj();if(!p?.logEntries?.length){el.innerHTML='<div style="text-align:center;padding:16px;color:var(--text-muted)">No entries.</div>';return}el.innerHTML=p.logEntries.map((e,i)=>`<div class="log-entry"><div class="log-header"><span class="log-type ${e.type==='Update'?'log-type-update':'log-type-accomplishment'}">${esc(e.type)}</span><div style="display:flex;gap:6px;align-items:center"><span class="log-date">${new Date(e.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span><button class="edit-toggle no-pdf" onclick="const n=prompt('Edit:',curProj().logEntries[${i}].text);if(n!==null){curProj().logEntries[${i}].text=n;saveProj(curView());renderPLogs()}">✏</button><button class="btn btn-sm btn-ghost no-pdf" onclick="curProj().logEntries.splice(${i},1);saveProj(curView());renderPLogs()" style="padding:2px 6px;color:var(--text-muted)">✕</button></div></div><div class="log-text">${esc(e.text)}</div></div>`).join('')}
function addPRisk(){const p=curProj(),t=document.getElementById('pRT').value.trim(),c=document.getElementById('pRC').value,sv=document.getElementById('pRS').value,ow=document.getElementById('pRO').value.trim();if(!t||!p)return;if(!p.risks)p.risks=[];p.risks.push({text:t,category:c,severity:sv,owner:ow,status:'New',date:new Date().toISOString()});document.getElementById('pRT').value='';document.getElementById('pRO').value='';saveProj(curView());renderPRisks()}
function renderPRisks(){const el=document.getElementById('pRL');if(!el)return;const p=curProj();if(!p?.risks?.length){el.innerHTML='<div style="text-align:center;padding:16px;color:var(--text-muted)">No risks.</div>';return}el.innerHTML=p.risks.map((r,i)=>`<div class="risk-card"><span class="priority-badge priority-${r.severity.toLowerCase()}">${esc(r.severity)}</span><span class="risk-cat-badge">${esc(r.category||'-')}</span><select class="no-pdf" style="font-size:11px;padding:3px 6px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary);width:130px" onchange="curProj().risks[${i}].status=this.value;saveProj(curView());renderPRisks()">${RISK_STATUSES.map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select><span class="risk-status-badge ${RSC[r.status]||'risk-new'}" style="display:none" data-pdf-badge>${esc(r.status)}</span><span style="flex:1">${esc(r.text)}</span><span style="font-size:12px;color:var(--text-secondary)">${esc(r.owner)||'-'}</span><button class="edit-toggle no-pdf" onclick="const n=prompt('Edit:',curProj().risks[${i}].text);if(n!==null){curProj().risks[${i}].text=n;saveProj(curView());renderPRisks()}">✏</button><button class="btn btn-sm btn-ghost no-pdf" onclick="curProj().risks.splice(${i},1);saveProj(curView());renderPRisks()" style="padding:2px 6px;color:var(--text-muted)">✕</button></div>`).join('')}

// TC TABLE
function rTT(){const p=curProj();if(!p)return;const sf=document.getElementById('sf')?.value?.toLowerCase()||'',stf=document.getElementById('stf')?.value||'',prf=document.getElementById('prf')?.value||'';const fl=p.testCases.filter(t=>{if(sf&&!t.tc_id.toLowerCase().includes(sf)&&!t.scenarioName.toLowerCase().includes(sf)&&!t.validationArea.toLowerCase().includes(sf))return false;if(stf&&t.status!==stf)return false;if(prf&&t.priority!==prf)return false;return true});const cn=document.getElementById('tcC');if(cn)cn.textContent=fl.length;
document.getElementById('tcB').innerHTML=fl.map(tc=>{const i=p.testCases.indexOf(tc),s='status-'+tc.status.toLowerCase().replace(/\s+/g,'-'),os=(tc.subItems||[]).filter(si=>!['Closed','Done'].includes(si.status)).length;return`<tr><td><button class="expand-btn" onclick="this.classList.toggle('open');document.getElementById('dr${i}').classList.toggle('open')">▶</button></td><td class="td-id" onclick="openTcModal2(${i})">${esc(tc.tc_id)}</td><td>${esc(tc.validationArea)}</td><td style="max-width:200px">${esc(tc.scenarioName)}</td><td style="max-width:160px;font-size:12px;color:var(--text-secondary)">${esc(tc.expectedResults)}</td><td><span class="type-badge">${esc(tc.typeOfTest)}</span></td><td><select class="priority-select" onchange="puf(${i},'priority',this.value)">${PRIORITIES.map(pr=>`<option ${pr===(tc.priority||'Medium')?'selected':''}>${pr}</option>`).join('')}</select></td><td><select class="status-select" onchange="pUS(${i},this.value)">${STATUSES.map(st=>`<option ${st===tc.status?'selected':''}>${st}</option>`).join('')}</select></td><td><select class="script-select" onchange="puf(${i},'scriptStatus',this.value)">${SCRIPT_STATUSES.map(s=>`<option ${s===(tc.scriptStatus||'Todo')?'selected':''}>${s}</option>`).join('')}</select></td><td style="text-align:center">${os>0?`<span style="font-family:var(--font-mono);font-size:12px;color:var(--accent)">${os}</span>`:'-'}</td></tr><tr class="detail-row" id="dr${i}"><td colspan="10"><div class="detail-content"><div style="display:flex;justify-content:flex-end;margin-bottom:8px"><button class="btn btn-sm btn-danger" onclick="pDelTc(${i})">🗑 Delete TC</button></div><div class="edit-fields"><div class="edit-field"><label>TC ID</label><input value="${esc(tc.tc_id)}" onchange="pUpdId(${i},this.value)"></div><div class="edit-field"><label>Scenario</label><input value="${esc(tc.scenarioName)}" onchange="puf(${i},'scenarioName',this.value)"></div></div><div class="edit-fields"><div class="edit-field"><label>Expected</label><input value="${esc(tc.expectedResults)}" onchange="puf(${i},'expectedResults',this.value)"></div><div class="edit-field"><label>Area</label><input value="${esc(tc.validationArea)}" onchange="puf(${i},'validationArea',this.value)"></div></div><div class="detail-box"><label>Details</label><textarea onchange="puf(${i},'tcDetails',this.value)">${esc(tc.tcDetails||'')}</textarea></div>${tc.status==='Blocked'?`<div class="blocking-reason"><label>⚠ Blocking Reason</label><select onchange="puf(${i},'blockingReason',this.value)"><option value="">— Select —</option>${BLOCKING_REASONS.map(r=>`<option ${tc.blockingReason===r?'selected':''}>${r}</option>`).join('')}</select><label>Details</label><textarea onchange="puf(${i},'blockingDetails',this.value)">${esc(tc.blockingDetails||'')}</textarea></div>`:''}<div class="detail-box"><label>Actual Results</label><textarea onchange="puf(${i},'actualResults',this.value)">${esc(tc.actualResults||'')}</textarea></div>${(()=>{const defs=(curProj().defects||[]).filter(d=>d.linkedTC===tc.tc_id);return defs.length?`<div class="sub-items-section"><h4>Linked Defects (${defs.length})</h4>${defs.map(d=>{const di=(curProj().defects||[]).indexOf(d);return`<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;margin-bottom:4px;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius)"><span style="font-family:var(--font-mono);font-size:12px;font-weight:600;color:var(--fail);cursor:pointer;text-decoration:underline;text-decoration-style:dotted;text-underline-offset:3px" onclick="openDefectView(${di})">${esc(d.id)}</span><span class="priority-badge priority-${d.severity.toLowerCase()}">${esc(d.severity)}</span><span class="defect-status ${DSC[d.status]||'ds-new'}">${esc(d.status)}</span><span style="flex:1;font-size:12px">${esc(d.title)}</span>${d.externalRef?(()=>{const rl=shortLink(d.externalRef);return`<a href="${esc(d.externalRef)}" target="_blank" rel="noopener" style="font-family:var(--font-mono);font-size:11px;color:var(--accent);text-decoration:underline">${esc(rl.toUpperCase())}</a>`})():''}</div>`}).join('')}</div>`:''})()}<div class="sub-items-section"><h4>Items (${(tc.subItems||[]).length})</h4>${(tc.subItems||[]).map((si,j)=>{const c=si.type==='Clarification'?'clarification':si.type==='Action Item'?'action-item':'dependency';return`<div class="sub-item"><span class="sub-item-type ${c}">${esc(si.type)}</span><input class="desc-input" value="${esc(si.description)}" placeholder="Desc" onchange="pUSub(${i},${j},'description',this.value)"><select style="width:90px;font-family:var(--font-mono);font-size:11px;padding:4px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)" onchange="pUSub(${i},${j},'status',this.value)">${SUB_STATUSES.map(s=>`<option ${si.status===s?'selected':''}>${s}</option>`).join('')}</select><input class="assignee-input" value="${esc(si.assignee)}" placeholder="Assignee" onchange="pUSub(${i},${j},'assignee',this.value)"><input class="date-input" type="date" value="${esc(si.dueDate)}" onchange="pUSub(${i},${j},'dueDate',this.value)"><button class="remove-sub" onclick="curProj().testCases[${i}].subItems.splice(${j},1);saveProj(curView());rTT();rAI()">✕</button></div>`}).join('')}<div><button class="btn btn-sm add-sub-btn" onclick="pASub(${i},'Clarification')">+ Clarification</button><button class="btn btn-sm add-sub-btn" onclick="pASub(${i},'Action Item')">+ Action Item</button><button class="btn btn-sm add-sub-btn" onclick="pASub(${i},'Dependency')">+ Dependency</button></div></div></div></td></tr>`}).join('')}
function puf(i,f,v){curProj().testCases[i][f]=v;saveProj(curView())}
function pUS(i,v){const tc=curProj().testCases[i];const wasFail=tc.status==='Fail';tc.status=v;if(v!=='Blocked'){tc.blockingReason='';tc.blockingDetails=''}saveProj(curView());if(v==='Fail'&&!wasFail){openDefectModal(tc.tc_id)}renderMain()}
function pUpdId(i,v){const p=curProj(),old=p.testCases[i].tc_id;p.testCases[i].tc_id=v;(p.requirements||[]).forEach(r=>{const x=r.linkedTCs.indexOf(old);if(x!==-1)r.linkedTCs[x]=v});(p.defects||[]).forEach(d=>{if(d.linkedTC===old)d.linkedTC=v});saveProj(curView());rTT();renderReqs()}
function pDelTc(i){const p=curProj(),tc=p.testCases[i];if(!confirm('Delete "'+tc.tc_id+'"?'))return;(p.requirements||[]).forEach(r=>{r.linkedTCs=r.linkedTCs.filter(t=>t!==tc.tc_id)});p.testCases.splice(i,1);saveProj(curView());renderMain();showToast('Deleted','success')}
function pASub(i,type){curProj().testCases[i].subItems.push({type,description:'',status:'New',assignee:'',dueDate:''});saveProj(curView());rTT();rAI()}
function pUSub(i,j,f,v){curProj().testCases[i].subItems[j][f]=v;saveProj(curView());rAI()}
function eAll(){document.querySelectorAll('.expand-btn').forEach(b=>{if(!b.classList.contains('open'))b.click()})}
function cAll(){document.querySelectorAll('.expand-btn.open').forEach(b=>b.click())}

// ACTION ITEMS
function rAI(){const p=curProj();if(!p)return;const tf=document.getElementById('aitf')?.value||'',sf=document.getElementById('aisf')?.value||'';let items=[];p.testCases.forEach((tc,ti)=>{(tc.subItems||[]).forEach((si,sii)=>{items.push({...si,tc_id:tc.tc_id,priority:tc.priority||'Medium',ti,sii})})});if(tf)items=items.filter(i=>i.type===tf);if(sf)items=items.filter(i=>i.status===sf);const cn=document.getElementById('aiC');if(cn)cn.textContent=items.length;const el=document.getElementById('aiL');if(!el)return;if(!items.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text-muted)">No items.</div>';return}el.innerHTML=items.map(i=>{const tc=i.type==='Clarification'?'clarification':i.type==='Action Item'?'action-item':'dependency';const sc=i.status==='Closed'||i.status==='Done'?'var(--success)':i.status==='New'?'var(--text-muted)':'var(--info)';return`<div class="action-item-card"><span class="tc-ref" onclick="openTcModal2(${i.ti})">${esc(i.tc_id)}</span><span class="priority-badge priority-${i.priority.toLowerCase()}">${esc(i.priority)}</span><span class="sub-item-type ${tc}">${esc(i.type)}</span><span>${esc(i.description)||'-'}</span><span style="font-size:12px;color:var(--text-secondary)">${esc(i.assignee)||'-'}</span><span style="font-family:var(--font-mono);font-size:11px;color:var(--text-muted)">${i.dueDate||'-'}</span><select style="font-family:var(--font-mono);font-size:11px;font-weight:600;padding:3px 6px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:${sc};width:90px" onchange="pUSub(${i.ti},${i.sii},'status',this.value);rAI()">${SUB_STATUSES.map(s=>`<option ${i.status===s?'selected':''}>${s}</option>`).join('')}</select></div>`}).join('')}

// DEFECTS
function renderDefs(){const p=curProj();if(!p)return;if(!p.defects)p.defects=[];const cn=document.getElementById('dfC');if(cn)cn.textContent=p.defects.length;const el=document.getElementById('dfL');if(!el)return;if(!p.defects.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text-muted)">No defects.</div>';return}
el.innerHTML=p.defects.map((df,i)=>{const refDisplay=df.externalRef?shortLink(df.externalRef):'';const isUrl=df.externalRef&&(df.externalRef.startsWith('http')||df.externalRef.startsWith('//'));
return`<div class="defect-card" id="df-${i}" style="display:block">
<div class="edit-view" style="display:flex;align-items:center;gap:10px;flex-wrap:wrap"><span class="defect-id" style="cursor:pointer;text-decoration:underline;text-decoration-style:dotted;text-underline-offset:3px" onclick="openDefectView(${i})">${esc(df.id)}</span><span class="priority-badge priority-${df.severity.toLowerCase()}">${esc(df.severity)}</span><span class="defect-status ${DSC[df.status]||'ds-new'}">${esc(df.status)}</span><span style="flex:1">${esc(df.title)}</span>${df.linkedTC?`<span class="td-id" onclick="const ti=curProj().testCases.findIndex(t=>t.tc_id==='${esc(df.linkedTC)}');if(ti>=0)openTcModal2(ti)">${esc(df.linkedTC)}</span>`:''} ${refDisplay?`<a href="${esc(df.externalRef)}" target="_blank" rel="noopener" style="font-family:var(--font-mono);font-size:11px;color:var(--accent);text-decoration:underline;text-underline-offset:2px">${esc(refDisplay.toUpperCase())}</a>`:''}<button class="edit-toggle no-pdf" onclick="document.getElementById('df-${i}').classList.add('editing')">✏</button><button class="btn btn-sm btn-ghost no-pdf" onclick="curProj().defects.splice(${i},1);saveProj(curView());renderDefs()" style="padding:2px 6px;color:var(--text-muted)">✕</button></div>
<div class="edit-form" style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:8px"><div><label style="font-size:10px;color:var(--text-muted);display:block;margin-bottom:4px">Title</label><input value="${esc(df.title)}" onchange="curProj().defects[${i}].title=this.value;saveProj(curView())" style="width:100%;font-size:13px;padding:6px 8px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"></div><div><label style="font-size:10px;color:var(--text-muted);display:block;margin-bottom:4px">External Link</label><input value="${esc(df.externalRef||'')}" onchange="curProj().defects[${i}].externalRef=this.value;saveProj(curView())" placeholder="https://jira.com/..." style="width:100%;font-size:13px;padding:6px 8px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"></div><div><label style="font-size:10px;color:var(--text-muted);display:block;margin-bottom:4px">Severity</label><select onchange="curProj().defects[${i}].severity=this.value;saveProj(curView())" style="width:100%;font-size:13px;padding:6px 8px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${PRIORITIES.map(p=>`<option ${df.severity===p?'selected':''}>${p}</option>`).join('')}</select></div><div><label style="font-size:10px;color:var(--text-muted);display:block;margin-bottom:4px">Status</label><select onchange="curProj().defects[${i}].status=this.value;saveProj(curView())" style="width:100%;font-size:13px;padding:6px 8px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${DEFECT_STATUSES.map(s=>`<option ${df.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div style="grid-column:span 2;text-align:right"><button class="btn btn-sm btn-primary" onclick="saveProj(curView());renderDefs()">Done</button></div></div>
</div>`}).join('')}

// REQUIREMENTS
function addReq(){const p=curProj();if(!p)return;const id=document.getElementById('rqI').value.trim(),d=document.getElementById('rqD').value.trim(),ref=document.getElementById('rqR')?.value?.trim()||'';if(!id||!d){showToast('ID and description required','error');return}if(!p.requirements)p.requirements=[];if(p.requirements.find(r=>r.id===id)){showToast('ID exists','error');return}p.requirements.push({id,description:d,reference:ref,linkedTCs:[]});document.getElementById('rqI').value='';document.getElementById('rqD').value='';if(document.getElementById('rqR'))document.getElementById('rqR').value='';saveProj(curView());renderReqs()}
function renderReqs(){const p=curProj();if(!p)return;if(!p.requirements)p.requirements=[];const cn=document.getElementById('rqC');if(cn)cn.textContent=p.requirements.length;const el=document.getElementById('rqL');if(!el)return;if(!p.requirements.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text-muted)">No requirements.</div>';return}el.innerHTML=p.requirements.map((r,i)=>{const cov=getReqCovP(r,p),cc=cov==='Covered'?'coverage-covered':cov==='Missing'?'coverage-missing':'coverage-at-risk';return`<div class="req-card"><div class="req-header"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span class="req-id">${esc(r.id)}</span><span class="coverage-badge ${cc}">${cov}</span>${r.reference?`<span style="font-size:11px;color:var(--text-muted);font-family:var(--font-mono)">ref: ${esc(r.reference)}</span>`:''}</div><div style="display:flex;gap:6px"><button class="edit-toggle no-pdf" onclick="const n=prompt('Edit description:',curProj().requirements[${i}].description);if(n!==null){curProj().requirements[${i}].description=n;saveProj(curView());renderReqs()}">✏</button><button class="btn btn-sm no-pdf" onclick="openLinkM(${i})">+ Link</button><button class="btn btn-sm btn-ghost no-pdf" onclick="curProj().requirements.splice(${i},1);saveProj(curView());renderReqs()" style="color:var(--text-muted)">✕</button></div></div><div style="font-size:13px;color:var(--text-secondary);margin-bottom:6px">${esc(r.description)}</div><div class="req-links">${r.linkedTCs.length?r.linkedTCs.map(tid=>{const f=p.testCases.find(t=>t.tc_id===tid),ti=f?p.testCases.indexOf(f):-1,si=f?'status-'+f.status.toLowerCase().replace(/\s+/g,'-'):'';return`<span class="req-link-chip"><span class="status-badge ${si}" style="padding:1px 6px;font-size:10px;cursor:pointer" onclick="openTcModal2(${ti})">${esc(tid)}</span><span class="remove-link no-pdf" onclick="curProj().requirements[${i}].linkedTCs=curProj().requirements[${i}].linkedTCs.filter(t=>t!=='${esc(tid)}');saveProj(curView());renderReqs()">✕</span></span>`}).join(''):'<span style="font-size:12px;color:var(--text-muted);font-style:italic">None</span>'}</div></div>`}).join('')}
function openLinkM(i){linkingReqIdx=i;const r=curProj().requirements[i];document.getElementById('linkReqLabel').textContent=r.id+' — '+r.description;const sel=document.getElementById('linkTcSelect'),av=curProj().testCases.filter(tc=>!r.linkedTCs.includes(tc.tc_id));sel.innerHTML=av.length?av.map(tc=>`<option value="${tc.tc_id}">${tc.tc_id} — ${tc.scenarioName}</option>`).join(''):'<option value="">None</option>';document.getElementById('linkModal').classList.add('open')}
function confirmLink(){const v=document.getElementById('linkTcSelect').value;if(!v){closeModal('linkModal');return}curProj().requirements[linkingReqIdx].linkedTCs.push(v);saveProj(curView());renderReqs();closeModal('linkModal')}

// TC MODAL
function openTcModal2(i){const p=curProj(),tc=p.testCases[i];const m=document.getElementById('tcModalContent');m.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><h3 style="margin:0">${esc(tc.tc_id)}</h3><button class="btn btn-sm btn-ghost" onclick="closeModal('tcModal');renderMain()" style="font-size:18px;padding:4px 8px">✕</button></div><div class="tc-modal-row"><div class="tc-modal-field"><label>Scenario</label><input value="${esc(tc.scenarioName)}" onchange="puf(${i},'scenarioName',this.value)"></div><div class="tc-modal-field"><label>Area</label><input value="${esc(tc.validationArea)}" onchange="puf(${i},'validationArea',this.value)"></div></div><div class="tc-modal-row"><div class="tc-modal-field"><label>Status</label><select onchange="pUS(${i},this.value);openTcModal2(${i})" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${STATUSES.map(s=>`<option ${s===tc.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="tc-modal-field"><label>Priority</label><select onchange="puf(${i},'priority',this.value)" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${PRIORITIES.map(p=>`<option ${p===(tc.priority||'Medium')?'selected':''}>${p}</option>`).join('')}</select></div></div><div class="tc-modal-row"><div class="tc-modal-field"><label>Expected</label><input value="${esc(tc.expectedResults)}" onchange="puf(${i},'expectedResults',this.value)"></div><div class="tc-modal-field"><label>Script</label><select onchange="puf(${i},'scriptStatus',this.value)" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${SCRIPT_STATUSES.map(s=>`<option ${s===(tc.scriptStatus||'Todo')?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="tc-modal-field"><label>Actual Results</label><textarea onchange="puf(${i},'actualResults',this.value)" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary);resize:vertical;min-height:50px">${esc(tc.actualResults||'')}</textarea></div>${tc.status==='Blocked'?`<div style="padding:12px;background:var(--blocked-bg);border:1px solid rgba(249,115,22,.3);border-radius:var(--radius);margin-bottom:14px"><label style="font-size:11px;font-weight:600;color:var(--blocked);display:block;margin-bottom:6px">BLOCKING REASON</label><select onchange="puf(${i},'blockingReason',this.value)" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid rgba(249,115,22,.3);background:var(--bg-input);color:var(--text-primary);margin-bottom:8px"><option value="">— Select —</option>${BLOCKING_REASONS.map(r=>`<option ${tc.blockingReason===r?'selected':''}>${r}</option>`).join('')}</select><label style="font-size:11px;font-weight:600;color:var(--blocked);display:block;margin-bottom:6px">BLOCKING DETAILS</label><textarea onchange="puf(${i},'blockingDetails',this.value)" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid rgba(249,115,22,.3);background:var(--bg-input);color:var(--text-primary);resize:vertical;min-height:40px">${esc(tc.blockingDetails||'')}</textarea></div>`:''}<div class="tc-modal-field"><label>Linked Defects</label>${(p.defects||[]).filter(d=>d.linkedTC===tc.tc_id).length?`<div style="display:flex;flex-wrap:wrap;gap:6px">${(p.defects||[]).filter(d=>d.linkedTC===tc.tc_id).map(d=>{const di=(p.defects||[]).indexOf(d);return`<span style="font-family:var(--font-mono);font-size:11px;padding:2px 8px;border-radius:4px;background:var(--fail-bg);color:var(--fail);border:1px solid rgba(239,68,68,.3);cursor:pointer;text-decoration:underline;text-decoration-style:dotted;text-underline-offset:2px" onclick="closeModal('tcModal');openDefectView(${di})">${esc(d.id)} — ${esc(d.status)}</span>`}).join('')}</div>`:'<span style="font-size:12px;color:var(--text-muted)">None</span>'}</div>`;document.getElementById('tcModal').classList.add('open')}

// DEFECT VIEW MODAL
function openDefectView(defIdx){const p=curProj();if(!p||!p.defects||!p.defects[defIdx])return;_renderDefectViewModal(p,defIdx,curView(),false)}
function openDefectViewCross(pid,defIdx){const prev=curView();curDash().currentView=pid;const p=projects[pid];if(!p||!p.defects||!p.defects[defIdx])return;_renderDefectViewModal(p,defIdx,pid,true)}
function _renderDefectViewModal(p,defIdx,pid,isCross){
const df=p.defects[defIdx];const refDisplay=df.externalRef?shortLink(df.externalRef):'';const isUrl=df.externalRef&&(df.externalRef.startsWith('http')||df.externalRef.startsWith('//'));
const closeAction=isCross?`closeModal('defectViewModal');curDash().currentView='cumulative';saveDash(meta.currentDashId);renderMain()`:`closeModal('defectViewModal');renderMain()`;
const saveCmd=`saveProj('${pid}')`;
const m=document.getElementById('defectViewContent');
m.innerHTML=`<div id="dfv-wrap">
<div class="edit-view">
<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><h3 style="margin:0;color:var(--fail)">${esc(df.id)}</h3><div style="display:flex;gap:6px"><button class="edit-toggle" onclick="document.getElementById('dfv-wrap').classList.add('editing')" style="font-size:16px">✏</button><button class="btn btn-sm btn-ghost" onclick="${closeAction}" style="font-size:18px;padding:4px 8px">✕</button></div></div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px">
<div><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">Title</span><span style="font-size:14px">${esc(df.title)}</span></div>
<div><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">Status</span><span class="defect-status ${DSC[df.status]||'ds-new'}">${esc(df.status)}</span></div>
<div><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">Severity</span><span class="priority-badge priority-${df.severity.toLowerCase()}">${esc(df.severity)}</span></div>
<div><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">Linked Test Case</span>${df.linkedTC?`<span class="td-id" onclick="closeModal('defectViewModal');${isCross?`openTcCross('${pid}',projects['${pid}'].testCases.findIndex(t=>t.tc_id==='${esc(df.linkedTC)}'))`:`const ti=curProj().testCases.findIndex(t=>t.tc_id==='${esc(df.linkedTC)}');if(ti>=0)openTcModal2(ti)`}">${esc(df.linkedTC)}</span>`:'<span style="font-size:12px;color:var(--text-muted)">None</span>'}</div>
<div><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">External Reference</span>${isUrl?`<a href="${esc(df.externalRef)}" target="_blank" rel="noopener" style="font-family:var(--font-mono);font-size:13px;color:var(--accent);text-decoration:underline">${esc(refDisplay.toUpperCase())}</a>`:(df.externalRef?`<span style="font-size:13px">${esc(df.externalRef)}</span>`:'<span style="font-size:12px;color:var(--text-muted)">None</span>')}</div>
<div><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">Date Logged</span><span style="font-size:13px;font-family:var(--font-mono)">${df.date?new Date(df.date).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}):'-'}</span></div>
</div>
${df.description?`<div style="margin-bottom:16px"><span style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:4px">Description</span><div style="font-size:13px;color:var(--text-secondary);background:var(--bg-input);border:1px solid var(--border);border-radius:var(--radius);padding:10px 12px;white-space:pre-wrap">${esc(df.description)}</div></div>`:''}
</div>
<div class="edit-form">
<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><h3 style="margin:0;color:var(--fail)">${esc(df.id)} — Edit</h3><button class="btn btn-sm btn-ghost" onclick="${closeAction}" style="font-size:18px;padding:4px 8px">✕</button></div>
<div class="tc-modal-field"><label>Title</label><input value="${esc(df.title)}" onchange="projects['${pid}'].defects[${defIdx}].title=this.value;${saveCmd}" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"></div>
<div class="tc-modal-row"><div class="tc-modal-field"><label>Severity</label><select onchange="projects['${pid}'].defects[${defIdx}].severity=this.value;${saveCmd}" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${PRIORITIES.map(pr=>`<option ${df.severity===pr?'selected':''}>${pr}</option>`).join('')}</select></div><div class="tc-modal-field"><label>Status</label><select onchange="projects['${pid}'].defects[${defIdx}].status=this.value;${saveCmd}" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)">${DEFECT_STATUSES.map(s=>`<option ${df.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div>
<div class="tc-modal-field"><label>External Reference (Link)</label><input value="${esc(df.externalRef||'')}" onchange="projects['${pid}'].defects[${defIdx}].externalRef=this.value;${saveCmd}" placeholder="https://jira.com/browse/BUG-001" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"></div>
<div class="tc-modal-field"><label>Description</label><textarea onchange="projects['${pid}'].defects[${defIdx}].description=this.value;${saveCmd}" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary);resize:vertical;min-height:60px">${esc(df.description||'')}</textarea></div>
<div class="tc-modal-field"><label>Linked Test Case</label><select onchange="projects['${pid}'].defects[${defIdx}].linkedTC=this.value;${saveCmd}" style="width:100%;font-size:13px;padding:8px 10px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-input);color:var(--text-primary)"><option value="">None</option>${p.testCases.map(tc=>`<option value="${tc.tc_id}" ${df.linkedTC===tc.tc_id?'selected':''}>${tc.tc_id} — ${tc.scenarioName}</option>`).join('')}</select></div>
<div style="text-align:right;margin-top:12px"><button class="btn btn-primary" onclick="document.getElementById('dfv-wrap').classList.remove('editing');${saveCmd};_renderDefectViewModal(projects['${pid}'],${defIdx},'${pid}',${isCross})">Done</button></div>
</div></div>`;
document.getElementById('defectViewModal').classList.add('open')}

